<script lang="ts">
import{onDestroy}from'svelte';import type{Language}from'./i18n';import type{SecurityEvent}from'./api';import{formatTime}from'./format';import{authenticationActivity,authenticationKinds,authenticationLabel,authenticationMeaning,identityLabel,logonTypeLabel,type AuthenticationKind,type AuthenticationPage}from'./identityActivity';
let{language,onEvent}:{language:Language;onEvent:(event:SecurityEvent)=>void}=$props();const it=$derived(language==='it');let open=$state(false),busy=$state(false),error=$state(''),loaded=$state(false),kind=$state(''),result=$state<AuthenticationPage|null>(null),page=$state(0),cursors=$state<Array<number|null>>([null]);let alive=true;onDestroy(()=>{alive=false;});
async function read(){if(busy)return;busy=true;error='';try{const value=await authenticationActivity(cursors[page],kind?kind as AuthenticationKind:null);if(alive){result=value;loaded=true;}}catch(e){if(alive){result=null;error=String(e);}}finally{if(alive)busy=false;}}
function reset(){page=0;cursors=[null];void read();}function older(){if(result?.next_before){cursors=[...cursors.slice(0,page+1),result.next_before];page++;void read();}}function newer(){if(page){page--;void read();}}
const name=(path:string|null)=>path?.split(/[\\/]/).at(-1)||(it?'Programma non disponibile':'Program unavailable');
</script>
<details class="panel identity-activity" bind:open ontoggle={(event)=>{if(event.currentTarget.open&&!loaded&&!busy)void read();}}>
<summary>{it?'Account, accessi e privilegi':'Accounts, logons and privileges'}</summary>
<div class="content"><div class="toolbar"><label>{it?'Mostra':'Show'}<select aria-label={it?'Categoria accessi':'Logon category'} bind:value={kind} disabled={busy} onchange={reset}><option value="">{it?'Tutte le categorie':'All categories'}</option>{#each authenticationKinds as item}<option value={item}>{authenticationLabel(item,language)}</option>{/each}</select></label><button class="button secondary small" disabled={busy} onclick={reset}>{it?'Aggiorna':'Refresh'}</button></div>
<p class="scope">{it?'Eventi Security già archiviati; cinque per pagina, ordinati per raccolta. Gli eventi ordinari non diventano avvisi nella dashboard.':'Already archived Security events; five per page, ordered by collection. Routine events do not become dashboard alerts.'}</p>
{#if busy}<p role="status">{it?'Lettura in corso…':'Loading…'}</p>{/if}{#if error}<p role="alert" class="error">{error}</p>{/if}
{#if loaded&&!busy&&result&&!result.records.length}<p>{it?'Nessun evento disponibile per questo filtro. Non dimostra assenza di accessi: dipende da audit Windows, permessi e conservazione.':'No event available for this filter. This does not prove no logons occurred: coverage depends on Windows auditing, permissions and retention.'}</p>{/if}
<ul>{#each result?.records??[] as record(record.event.event_id)}<li class:attention={record.kind==='failed_logon'||record.kind==='special_privileges'||record.kind.startsWith('account_')}><div class="row"><div><strong>{identityLabel(record.context.account,language)}</strong><small>{authenticationLabel(record.kind,language)} · {formatTime(record.event.wall_clock_time,language)}</small></div>{#if !record.kind.startsWith('account_')}<span class="type">{logonTypeLabel(record.context.logon_type,language)}</span>{/if}</div>
<details class="record-details"><summary>{it?'Dettagli e verifiche consigliate':'Details and suggested checks'}</summary><p>{authenticationMeaning(record.kind,language)}</p>
{#if record.context.evidence_status!=='verified'}<p class="warning">{it?'Campi XML non disponibili o non supportati: consulta il record grezzo.':'XML fields unavailable or unsupported: inspect the raw record.'} ({record.context.evidence_status})</p>{:else}
<dl><dt>{it?'Account richiedente':'Requesting account'}</dt><dd>{identityLabel(record.context.subject,language)}</dd>{#if !record.kind.startsWith('account_')}<dt>{it?'Programma chiamante riportato':'Reported caller'}</dt><dd>{name(record.context.caller_path)}{record.context.caller_pid ? ' · PID '+record.context.caller_pid : ''}<code>{record.context.caller_path??''}</code></dd><dt>{it?'Indirizzo riportato da Windows':'Address reported by Windows'}</dt><dd>{record.context.address??'—'}</dd><dt>{it?'Computer / server indicato':'Reported workstation / server'}</dt><dd>{record.context.workstation??record.context.target_server??'—'}</dd>{/if}<dt>{record.kind==='successful_logon'?(it?'Sessione creata':'Created session'):(it?'Sessione del soggetto':'Subject session')}</dt><dd><code>{record.context.logon_id??'—'}</code></dd>{#if !record.kind.startsWith('account_')}<dt>{it?'Metodo di autenticazione':'Authentication package'}</dt><dd>{record.context.authentication_package??'—'}</dd>{/if}</dl>
{#if record.context.privileges.length}<details><summary>{it?'Privilegi riportati':'Reported privileges'} · {record.context.privileges.length}</summary><ul>{#each record.context.privileges as privilege}<li><code>{privilege}</code></li>{/each}</ul></details>{/if}
{/if}<p>{it?'Se non riconosci l’attività, verifica account, orario, programma e accessi remoti con l’amministratore. Per errori ripetuti controlla prima le credenziali salvate. Nessun account viene bloccato automaticamente.':'If activity is unexpected, review the account, time, program and remote access with your administrator. For repeated failures check saved credentials first. No account is automatically blocked.'}</p>
<button class="text-button" onclick={()=>onEvent(record.event)}>{it?'Apri evento e dati grezzi':'Open event and raw data'}</button></details></li>{/each}</ul>
{#if result}<nav aria-label={it?'Pagine accessi':'Logon pages'}><button class="text-button" disabled={busy||page===0} onclick={newer}>{it?'Più recenti':'Newer'}</button><span>{it?'Pagina':'Page'} {page+1}</span><button class="text-button" disabled={busy||result.next_before===null} onclick={older}>{it?'Più vecchi':'Older'}</button></nav>{/if}
<details class="limits"><summary>{it?'Copertura':'Coverage'}</summary><p>{it?'4624, 4625, 4648, 4672, 4720, 4722, 4725 e 4726. Gli ID di sessione possono essere riutilizzati dopo il riavvio: non sono collegati automaticamente tra eventi. Il programma chiamante non identifica necessariamente una persona o un attaccante remoto.':'4624, 4625, 4648, 4672, 4720, 4722, 4725 and 4726. Logon IDs can be reused after reboot: events are not automatically linked. The caller does not necessarily identify a person or remote attacker.'}</p></details>
</div></details>
<style>.identity-activity{padding:18px 22px}summary{cursor:pointer;font-size:.83rem}.content{padding-top:16px}.toolbar,.row,nav{display:flex;gap:16px;align-items:center;justify-content:space-between}.toolbar label{display:flex;align-items:center;gap:10px;font-size:.76rem}select{max-width:260px}p,small,dt,dd,nav,.type{font-size:.76rem;line-height:1.7}p,small,dt,nav,.type{color:var(--muted)}ul{list-style:none;padding:0}li{padding:14px 12px;border-bottom:1px solid var(--border);border-left:3px solid transparent}.attention{border-left-color:var(--warning)}strong,small,code{display:block}strong{font-size:.83rem;overflow-wrap:anywhere}code,dd{overflow-wrap:anywhere}code{font-size:.7rem}.record-details{margin-top:10px}.record-details>summary{color:var(--accent)}dl{display:grid;grid-template-columns:1fr 2fr;gap:8px}dd{margin:0}.error{color:var(--danger)}.warning{color:var(--warning)}.limits{margin-top:16px}@media(max-width:650px){.toolbar,.row{align-items:flex-start;flex-wrap:wrap}dl{grid-template-columns:1fr}.type{max-width:100%}}</style>
